import System.ArgumentException;import System.Exception;import System.InvalidOperationException;import System.NullReferenceException;import java.nio.file.*;import java.util.*;import java.lang.reflect.Method;
class ArgumentExceptionMessageParametersProbe{
 static String text(String csv){if(csv.equals("~"))return null;if(csv.isEmpty())return "";String[] p=csv.split(",");char[] c=new char[p.length];for(int i=0;i<c.length;i++)c[i]=(char)Integer.parseInt(p[i]);return new String(c);}static String units(String text){if(text==null)return "~";StringJoiner out=new StringJoiner(",");for(char c:text.toCharArray())out.add(Integer.toString(c));return out.toString();}static void check(boolean b,String c){if(!b)throw new AssertionError(c);}
 static ArgumentException make(String ctor,String message,String param,Exception inner){return switch(ctor){case "default"->new ArgumentException();case "message"->new ArgumentException(message);case "messageInner"->new ArgumentException(message,inner);case "messageParam"->new ArgumentException(message,param);case "messageParamInner"->new ArgumentException(message,param,inner);default->throw new AssertionError(ctor);};}
 public static void main(String[] args)throws java.lang.Exception{int cases=0,observations=0,groups=0;ArgumentException current=null;Method set=Exception.class.getDeclaredMethod("set_HResult",int.class);set.setAccessible(true);for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);if(p[0].equals("N")){current=make(p[1],text(p[2]),text(p[3]),null);continue;}if(p[0].equals("Q")){set.invoke(current,Integer.parseInt(p[1]));check(current.get_HResult()==Integer.parseInt(p[1]),"HRESULT mutation "+line);check(units(current.get_Message()).equals(p[2]),"cached message "+line+" actual="+units(current.get_Message()));check(units(current.get_ParamName()).equals(p[3]),"cached parameter "+line);groups+=3;observations++;continue;}
 int kind=Integer.parseInt(p[4]);Exception inner=kind==1?new InvalidOperationException("inner-value"):kind==2?new NullReferenceException():null;ArgumentException value=make(p[1],text(p[2]),text(p[3]),inner);check(units(value.get_Message()).equals(p[5]),"message "+line+" actual="+units(value.get_Message()));check(value.getClass().getName().equals(p[6]),"type "+line);check(value.get_HResult()==Integer.parseInt(p[7]),"HRESULT "+line);check(units(value.get_ParamName()).equals(p[8]),"parameter "+line);check((value.get_InnerException()!=null)==p[9].equals("1"),"inner presence "+line);check(Objects.equals(value.get_InnerException()==null?null:value.get_InnerException().getClass().getName(),p[10].equals("~")?null:p[10]),"inner type "+line);check(units(value.get_InnerException()==null?null:value.get_InnerException().get_Message()).equals(p[11]),"inner message "+line);check((value.get_InnerException()==inner)==p[12].equals("1"),"inner identity "+line);check((value.GetBaseException()==(inner==null?value:inner))==p[13].equals("1"),"base identity "+line);cases++;groups+=9;
 }java.lang.System.out.println("PASS ArgumentException messages cases="+cases+" observations="+observations+" groups="+groups);}
}
